    internal void Normalize(){if(LockText==null)LockText=new EnemyHealthOptions().LockText;LockText.Normalize();LockText.Marker=false;if(Bar==null)Bar=new EnemyHealthOptions().Bar;Bar.Normalize();Bar.AutoHide=false;if(!EnergyBarOptions.ValidColor(SelfColor))SelfColor="#EF986B";if(!EnergyBarOptions.ValidColor(SelfNameColor))SelfNameColor="#B7DEED";if(Details==null)Details=new EnemyDetailOptions();Details.Normalize();if(Name==null)Name=new EnemyNameOptions();Name.Normalize();Bounds=new Rectangle(Math.Max(-100000,Math.Min(100000,Bounds.X)),Math.Max(-100000,Math.Min(100000,Bounds.Y)),Math.Max(80,Math.Min(2400,Bounds.Width)),Math.Max(3,Math.Min(80,Bounds.Height)));}
    internal static EnemyHealthOptions Read(Dictionary<string,object> cfg,string section="enemyHealth"){object value;var o=section=="enemyTarget"?TargetDefaults():new EnemyHealthOptions();if(cfg.TryGetValue(section,out value))try{o=new JavaScriptSerializer().ConvertToType<EnemyHealthOptions>(value)??o;}catch(ArgumentException){}var legacy=value as Dictionary<string,object>;if(section=="enemyTarget"&&legacy!=null&&!legacy.ContainsKey("Details"))o.Details=TargetDefaults().Details;if(section=="enemyTarget"&&legacy!=null&&!legacy.ContainsKey("SelfNameColor")&&o.Name!=null)o.SelfNameColor=o.Name.Color;if(section=="enemyTarget"&&legacy!=null&&!legacy.ContainsKey("SelfHighlight"))o.SelfHighlight=true;if(legacy!=null&&!legacy.ContainsKey("Name")&&o.Bar!=null)o.Name.FontSize=Math.Max(14,Math.Min(36,(int)Math.Round(o.Bar.TextSize*1.5)));if(o.Bar!=null&&!o.Bar.DynamicColors&&o.Bar.MediumColor=="#BD333B"&&o.Bar.LowColor=="#BD333B"&&o.Bar.HighColor=="#BD333B"){o.Bar.MediumColor=o.Bar.LowColor=o.Bar.HighColor="#EB423D";if(o.Bar.CurrentOffsetY==0&&o.Bar.MaximumOffsetY==0&&o.Bar.PercentageOffsetY==0)o.Bar.CurrentOffsetY=o.Bar.MaximumOffsetY=o.Bar.PercentageOffsetY=8;}o.Normalize();return o;}
}

internal static class EnemyNames {
    public sealed class Entry {public string en {get;set;}public string es {get;set;}}
    static readonly Dictionary<string,Entry> names=Load();
    static Dictionary<string,Entry> Load(){try{using(var stream=typeof(EnemyNames).Assembly.GetManifestResourceStream("Aion2NpcNames.json")){if(stream==null)return new Dictionary<string,Entry>();using(var reader=new StreamReader(stream))return new JavaScriptSerializer{MaxJsonLength=4000000}.Deserialize<Dictionary<string,Entry>>(reader.ReadToEnd());}}catch(IOException){return new Dictionary<string,Entry>();}catch(ArgumentException){return new Dictionary<string,Entry>();}}
    internal static string Name(uint id,string language){Entry entry;if(names.TryGetValue(id.ToString(CultureInfo.InvariantCulture),out entry)&&entry!=null&&!string.IsNullOrEmpty(entry.en))return language=="es"&&!string.IsNullOrEmpty(entry.es)?entry.es:entry.en;return language=="es"?"Enemigo":"Enemy";}
}

// Passive, bounded state on the existing decoder. No selected-target memory read.
// 3438 was validated with Tab A/B and clear; 3538 also carries NPC aggro and
// is deliberately not used. Cast aim precedes area impacts and passive procs.
internal sealed class EnemyHealthSignal {
    internal sealed class Sample {internal uint Actor,Npc,Current,Maximum;internal string Flow,Name,DistanceStatus;internal double Time,Traffic;internal bool Locked,IsSelf;internal int? BaseLevel,AdjustedLevel;internal EnemyDetailReader.Position Position;internal double? Distance;}
    sealed class Flow {internal readonly Dictionary<uint,Sample> Npcs=new Dictionary<uint,Sample>();internal readonly HashSet<uint> Skills=new HashSet<uint>();internal uint Map,Locked,Soft,Self;internal int SelfLevel;internal EnemyDetailReader.Position SelfPosition;internal double Traffic,AimTime;}
    readonly object gate=new object();readonly Dictionary<string,Flow> flows=new Dictionary<string,Flow>();volatile bool enabled;string selfFlow;internal Action Changed;internal ClientPositionReader ClientPositions;internal void PositionsChanged(){Notify();}
    internal void Configure(bool value){lock(gate){if(enabled==value)return;enabled=value;flows.Clear();selfFlow=null;}}
    internal void Reset(){lock(gate){flows.Clear();selfFlow=null;}Notify();}
    void Notify(){var changed=Changed;if(changed!=null)changed();}
    internal static bool Fresh(Sample s,double utc){return s!=null&&s.Current>0&&s.Maximum>0&&Math.Max(0,utc-s.Traffic)<=10;}
    internal Sample Actor(string key,uint actor){lock(gate){Flow f;Sample s;if(!flows.TryGetValue(key,out f)||!f.Npcs.TryGetValue(actor,out s))return null;return Clone(s,f,key,false);}}
    internal Sample Read(){lock(gate){Flow f;Sample s;if(selfFlow==null||!flows.TryGetValue(selfFlow,out f)||!f.Npcs.TryGetValue(f.Locked!=0?f.Locked:f.Soft,out s))return null;return Clone(s,f,selfFlow,f.Locked!=0);}}
    Sample Clone(Sample s,Flow f,string key,bool locked){double now=DpsHistory.UtcNow();bool exact=ClientPositions!=null&&ClientPositions.Enabled;var reading=exact?ClientPositions.Read(key,now):null;var position=exact?(reading==null?new EnemyDetailReader.Position():reading.Position):f.SelfPosition;double? distance=EnemyDetailReader.Distance(position,s.Position,now,exact);return new Sample{Actor=s.Actor,Npc=s.Npc,Current=s.Current,Maximum=s.Maximum,Time=s.Time,Traffic=f.Traffic,Flow=key,Locked=locked,BaseLevel=s.BaseLevel,AdjustedLevel=f.SelfLevel==45?(int?)45:f.SelfLevel>0?s.BaseLevel:null,Position=s.Position,Distance=distance,DistanceStatus=exact?(reading==null?ClientPositions.ReadingStatus:distance.HasValue?"Exact distance live":"No confirmed enemy position"):!position.Known?"No confirmed player position":!s.Position.Known?"No confirmed enemy position":Math.Max(0,now-position.Time)>5?"Player position older than five seconds":"Confirmed positions"};}
    static readonly int[] DescriptionBits={2,4,8,16},DescriptionSizes={1,1,5,1},StateBits={1,2,4,8,16,32},StateSizes={12,4,2,12,12,4};
    static bool Skip(ref int p,int end,int n){if(n<0||p>end-n)return false;p+=n;return true;}
    // Validates the bounded spawn prefix and its explicit initial/current max.
    // Unknown tails do not provide level, category, or a fabricated maximum.
    internal static bool Spawn(byte[] b,int start,int end,out Sample sample){sample=null;int p=start+2;uint actor,code,hp,max,n;EnemyDetailReader.Position position;int outer=0;if(!DpsSignal.Var(b,ref p,end,out actor)||actor==0||p>end-2)return false;outer=BitConverter.ToUInt16(b,p);p+=2;if(p>=end)return false;int desc=b[p++];if(desc>31)return false;if((desc&1)!=0&&(!DpsSignal.Var(b,ref p,end,out n)||n>160||!Skip(ref p,end,(int)n)))return false;if(p+4>end)return false;code=BitConverter.ToUInt32(b,p);p+=4;if(code<2000000||code>=3000000)return false;for(int i=0;i<DescriptionBits.Length;i++)if((desc&DescriptionBits[i])!=0&&!Skip(ref p,end,DescriptionSizes[i]))return false;if(p+2>end)return false;int state=BitConverter.ToUInt16(b,p);p+=2;EnemyDetailReader.Coordinates(b,p,end,out position);if(!Skip(ref p,end,18))return false;for(int i=0;i<StateBits.Length;i++)if((state&StateBits[i])!=0&&!Skip(ref p,end,StateSizes[i]))return false;if(!Skip(ref p,end,1)||!DpsSignal.Var(b,ref p,end,out hp)||!DpsSignal.Var(b,ref p,end,out max)||max==0||max>1000000000||hp>max||!Skip(ref p,end,52))return false;sample=new Sample{Actor=actor,Npc=code,Current=hp,Maximum=max,Position=position,BaseLevel=EnemyDetailReader.BaseLevel(b,p,end,outer,state)};return true;}
    internal static bool Points(byte[] b,int start,int end,out uint actor,out uint? current,out uint? maximum,out bool energy){actor=0;current=maximum=null;energy=false;int p=start+2;if(!DpsSignal.Var(b,ref p,end,out actor)||actor==0||p>=end)return false;int flags=b[p++];if(flags>3)return false;for(int width=4;width<=8;width+=4)if((flags&(width==4?1:2))!=0){uint count;if(!DpsSignal.Var(b,ref p,end,out count)||count>(end-p)/(width+1))return false;for(uint i=0;i<count;i++){int kind=b[p++];if(width==4&&kind==3)energy=true;if(width==8&&(kind==0||kind==7)){long v=BitConverter.ToInt64(b,p);if(v<0||v>1000000000)return false;if(kind==0)current=(uint)v;else maximum=(uint)v;}p+=width;}}return p==end;}
    internal static bool Selection(byte[] b,int start,int end,out uint actor){actor=0;int p=start+2;return end-start>=6&&b[p++]==0&&b[p++]==0&&b[p++]==0&&DpsSignal.Var(b,ref p,end,out actor)&&p==end&&actor<=10000000;}
    internal static bool Aim(byte[] b,int start,int end,out uint source,out uint target,out uint skill){source=target=skill=0;int p=start+2;if(!DpsSignal.Var(b,ref p,end,out source)||source==0||!Skip(ref p,end,1)||p+6>end)return false;skill=BitConverter.ToUInt32(b,p);p+=4;byte flags=b[p+1];p+=2;if(!DpsSignal.Var(b,ref p,end,out target)||target==0||target==source||p+4>end)return false;float facing=BitConverter.ToSingle(b,p);p+=4;if(float.IsNaN(facing)||float.IsInfinity(facing)||Math.Abs(facing)>720)return false;if((flags&2)!=0){if(p+12>end)return false;for(int i=0;i<3;i++){float v=BitConverter.ToSingle(b,p+i*4);if(float.IsNaN(v)||float.IsInfinity(v)||Math.Abs(v)>10000000)return false;}}return skill/1000000>=11&&skill/1000000<=19;}
    static bool Primary(Flow f,uint skill){return skill%100!=7&&skill%100!=8&&skill%100!=9&&!DpsSignal.HealingSkill(skill)&&!SkillCatalogue.Shared.IsNonDamage(skill)&&(f.Skills.Contains(skill)||skill%100>=10&&skill%100<=69);}
    void Trim(Flow f){if(f.Npcs.Count<512)return;uint remove=0;double oldest=double.MaxValue;foreach(var pair in f.Npcs)if(pair.Key!=f.Locked&&pair.Key!=f.Soft&&pair.Value.Time<oldest){remove=pair.Key;oldest=pair.Value.Time;}if(remove!=0)f.Npcs.Remove(remove);}
    internal void Consume(byte[] b,int start,int end,double time,string key){if(!enabled||b==null||start<0||end>b.Length||end-start<2||end-start>65536||key==null||double.IsNaN(time)||double.IsInfinity(time))return;bool changed=false;lock(gate){if(!enabled)return;Flow f;if(!flows.TryGetValue(key,out f)){if(flows.Count>=4){string remove=null;double oldest=double.MaxValue;foreach(var pair in flows)if(pair.Key!=selfFlow&&pair.Value.Traffic<oldest){remove=pair.Key;oldest=pair.Value.Traffic;}if(remove==null)return;flows.Remove(remove);}flows[key]=f=new Flow();}if(f.Traffic>0&&time-f.Traffic>30){f.Npcs.Clear();f.Locked=f.Soft=f.Self=0;f.SelfLevel=0;f.SelfPosition=new EnemyDetailReader.Position();f.Skills.Clear();if(selfFlow==key)selfFlow=null;changed=true;}f.Traffic=Math.Max(f.Traffic,time);int op=(b[start]<<8)|b[start+1],p=start+2;uint actor,source,target,skill;uint? current,max;bool energy;string name;byte role;EnemyDetailReader.Position fPosition;
        if(op==0x2136&&end-start==48&&BitConverter.ToUInt32(b,start+2)<=10000){uint map=BitConverter.ToUInt32(b,start+6);if(map>0&&map<10000000){if(f.Map!=0&&f.Map!=map){f.Npcs.Clear();f.Locked=f.Soft=f.Self=0;f.SelfPosition=new EnemyDetailReader.Position();f.AimTime=0;f.Skills.Clear();if(selfFlow==key)selfFlow=null;changed=true;}f.Map=map;}}
        else if(op==0x3336&&DpsSignal.PlayerIdentity(b,start,end,true,out actor,out name,out role)){if(f.Self!=0&&f.Self!=actor){f.Locked=f.Soft=0;f.Npcs.Clear();}f.Self=actor;selfFlow=key;int level;EnemyDetailReader.Position position;if(EnemyDetailReader.Character(b,start,end,out level,out position)){f.SelfLevel=level;position.Time=time;f.SelfPosition=position;}changed=true;}
        else if(op==0x0051){List<CharacterSkillEntry> entries;if(CharacterSkillState.Parse(b,start,end,SkillCatalogue.Shared,out entries)){f.Skills.Clear();foreach(var e in entries)f.Skills.Add(e.Id);}}
        else if(op==0x4136){Sample spawn;if(Spawn(b,start,end,out spawn)){Sample old;if(f.Npcs.TryGetValue(spawn.Actor,out old)&&time<old.Time)return;Trim(f);spawn.Time=time;spawn.Position.Time=time;spawn.Flow=key;if(!spawn.BaseLevel.HasValue&&old!=null&&old.Npc==spawn.Npc)spawn.BaseLevel=old.BaseLevel;f.Npcs[spawn.Actor]=spawn;changed=spawn.Actor==f.Locked||spawn.Actor==f.Soft;}}
        else if(op==0x008d&&Points(b,start,end,out actor,out current,out max,out energy)){if(energy){if(f.Self!=0&&f.Self!=actor){f.Locked=f.Soft=0;f.Npcs.Clear();}f.Self=actor;selfFlow=key;changed=true;}Sample s;if(f.Npcs.TryGetValue(actor,out s)&&time>=s.Time){uint nextMax=max.HasValue?max.Value:s.Maximum;uint nextCurrent=current.HasValue?current.Value:s.Current;if(nextMax>0&&nextCurrent<=nextMax){s.Maximum=nextMax;s.Current=nextCurrent;s.Time=time;changed|=actor==f.Locked||actor==f.Soft;if(nextCurrent==0){if(f.Locked==actor){f.Locked=0;f.Soft=0;}if(f.Soft==actor)f.Soft=0;}}}}
        else if(EnemyDetailReader.Movement(b,start,end,out actor,out fPosition)){fPosition.Time=time;if(actor==f.Self){if(!f.SelfPosition.Known||time>=f.SelfPosition.Time){f.SelfPosition=fPosition;changed=f.Locked!=0||f.Soft!=0;}}else {Sample moved;if(f.Npcs.TryGetValue(actor,out moved)&&(!moved.Position.Known||time>=moved.Position.Time)){moved.Position=fPosition;changed=actor==f.Locked||actor==f.Soft;}}}
        else if(op==0x3438&&Selection(b,start,end,out actor)){f.Locked=actor;if(actor==0)f.Soft=0;changed=true;}
        else if(op==0x4236&&DpsSignal.Var(b,ref p,end,out actor)&&end-p==2&&b[p]==0){f.Npcs.Remove(actor);if(f.Locked==actor){f.Locked=f.Soft=0;changed=true;}if(f.Soft==actor){f.Soft=0;changed=true;}}
        else if((op==0x0238||op==0x0938)&&key==selfFlow&&Aim(b,start,end,out source,out target,out skill)&&source==f.Self&&Primary(f,skill)&&f.Npcs.ContainsKey(target)){changed=f.Soft!=target;f.Soft=target;f.AimTime=time;}
        else if(op==0x0438&&key==selfFlow){DpsSignal.Hit hit;if(DpsSignal.Direct(b,start,end,out hit)&&hit.Source==f.Self&&hit.Target!=f.Self&&Primary(f,hit.Skill)&&f.Npcs.ContainsKey(hit.Target)&&time-f.AimTime>2){f.Soft=hit.Target;f.AimTime=time;changed=true;}}
    }if(changed)Notify();}
}

internal sealed class EnemyHealthOverlay:Form {
    readonly EnergyOverlay owner;readonly EnemyHealthSignal signal;readonly bool preview;readonly EnemyTargetSignal targetSignal;readonly LayeredImage image=new LayeredImage();readonly BarDesign.GlowWorkspace glow=new BarDesign.GlowWorkspace();readonly ProgressTextOverlay texts=new ProgressTextOverlay();readonly EnemyNameOverlay titleOverlay=new EnemyNameOverlay(),distanceOverlay=new EnemyNameOverlay(),speciesOverlay=new EnemyNameOverlay(),lockOverlay=new EnemyNameOverlay();readonly BarMotion motion=new BarMotion();readonly Stopwatch clock=Stopwatch.StartNew();readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();EnemyHealthOptions options=new EnemyHealthOptions(),selfOptions;bool editing,disposed,dragging;int queued,hit;Rectangle original;Point mouse,presented;string renderKey,actorKey;byte alpha;double raise;
    Rectangle Core {get{return new Rectangle(Left+5,Top+51,Width-10,options.Bounds.Height);}set{Bounds=new Rectangle(value.X-5,value.Y-51,value.Width+10,value.Height+87);}}
    internal EnemyHealthOverlay(EnergyOverlay owner,EnemyHealthSignal signal,bool preview,EnemyTargetSignal target=null){this.owner=owner;this.signal=signal;this.preview=preview;targetSignal=target;FormBorderStyle=FormBorderStyle.None;AutoScaleMode=AutoScaleMode.None;StartPosition=FormStartPosition.Manual;TopMost=true;ShowInTaskbar=false;Text="Aion 2 Helper - Enemy health";timer.Interval=250;timer.Tick+=delegate{Pulse();};if(targetSignal==null)signal.Changed=Wake;}
    internal void Configure(EnemyHealthOptions next,bool locked){options=next.Copy();options.Normalize();if(targetSignal!=null)options.Bar.CurrentText=options.Bar.MaximumText=options.Bar.PercentageText=false;selfOptions=options.Copy();selfOptions.Name.Color=options.SelfNameColor;selfOptions.Bar.DynamicColors=false;selfOptions.Bar.LowColor=selfOptions.Bar.MediumColor=selfOptions.Bar.HighColor=options.SelfColor;editing=!locked;Core=options.Bounds;int style=OverlayNative.GetWindowLong(Handle,-20);OverlayNative.SetWindowLong(Handle,-20,editing?style&~0x20:style|0x20);renderKey=null;if(options.Bar.Enabled)timer.Start();else{timer.Stop();if(Visible)Hide();texts.Clear();titleOverlay.Clear();distanceOverlay.Clear();speciesOverlay.Clear();lockOverlay.Clear();}Pulse();}
    void Wake(){if(disposed||!IsHandleCreated||Interlocked.CompareExchange(ref queued,1,0)!=0)return;try{BeginInvoke((Action)delegate{Interlocked.Exchange(ref queued,0);Pulse();});}catch(InvalidOperationException){Interlocked.Exchange(ref queued,0);}}
    internal static bool SelectionAllowed(EnemyHealthOptions options,EnemyHealthSignal.Sample enemy){return !options.OnlyLocked||(enemy!=null&&enemy.Locked);}
    internal static string LockCaption(bool locked,string language){return language=="es"?(locked?"Bloqueado":"Sin bloquear"):(locked?"Locked":"Unlocked");}
    EnemyHealthSignal.Sample Read(){var s=signal.Read();if(!SelectionAllowed(options,s))return null;return targetSignal==null?s:targetSignal.Read(s,signal);}
    string NameOf(EnemyHealthSignal.Sample s){return s.Name??EnemyNames.Name(s.Npc,owner.Language);}
    string CaptionOf(EnemyHealthSignal.Sample s){string level=targetSignal==null&&options.Details.Level?EnemyDetailReader.LevelText(s.AdjustedLevel,s.BaseLevel,options.Details.BaseLevel):"";return level.Length==0?NameOf(s):level+" · "+NameOf(s);}
    internal string ReadingStatus {get{var s=Read();return !options.Bar.Enabled?(targetSignal==null?"Enemy health disabled":"Enemy target disabled"):s==null?(options.OnlyLocked?"Lock an enemy with Tab":targetSignal==null?"Waiting for an enemy attack or target selection":"Waiting for confirmed enemy target and health"):s.Current==0?"Enemy defeated":NameOf(s);}}
    internal string StatusKey {get{var s=Read();return options.Bar.Enabled+"/"+Visible+"/"+(s==null?"":s.Actor+"/"+s.Current+"/"+s.Maximum+"/"+s.Locked+"/"+s.IsSelf+"/"+s.Npc+"/"+s.BaseLevel+"/"+s.AdjustedLevel+"/"+(s.Distance.HasValue?Math.Floor(s.Distance.Value).ToString():""));}}
    internal object Status {get{var s=Read();return new{enabled=options.Bar.Enabled,visible=Visible,onlyWithLockedEnemy=options.OnlyLocked,lockStatusEnabled=targetSignal==null&&options.LockText.Enabled,actor=s==null?0:s.Actor,npc=s==null?0:s.Npc,current=s==null?0:s.Current,maximum=s==null?0:s.Maximum,name=s==null?null:NameOf(s),baseLevel=s==null?null:s.BaseLevel,displayLevel=s==null?null:s.AdjustedLevel,distanceMeters=s==null?null:s.Distance,distanceStatus=targetSignal!=null?"Not used on enemy target":s==null?"No enemy":s.DistanceStatus,species=s==null?null:EnemySpecies.Name(s.Npc,owner.Language),isSelf=s!=null&&s.IsSelf,nameColor=s!=null&&s.IsSelf&&options.SelfHighlight?options.SelfNameColor:options.Name.Color,color=s!=null&&s.IsSelf&&options.SelfHighlight?options.SelfColor:options.Bar.MediumColor,locked=s!=null&&s.Locked,selection=targetSignal==null?"Hard target first; primary skill aim otherwise":"Received enemy focus",experimental=true,x=Core.X,y=Core.Y,width=Core.Width,height=Core.Height};}}
    static GraphicsPath Rounded(float x,float y,float width,float height){var path=new GraphicsPath();float d=Math.Min(height,width);if(d<=0)return path;path.AddArc(x,y,d,d,180,90);path.AddArc(x+width-d,y,d,d,270,90);path.AddArc(x+width-d,y+height-d,d,d,0,90);path.AddArc(x,y+height-d,d,d,90,90);path.CloseFigure();return path;}
    static void DrawCaption(Graphics g,string value,Font font,Color color,RectangleF rect,StringFormat format){using(var shadow=new SolidBrush(Color.FromArgb(220,0,0,0)))g.DrawString(value,font,shadow,new RectangleF(rect.X,rect.Y+1,rect.Width,rect.Height),format);using(var brush=new SolidBrush(color))g.DrawString(value,font,brush,rect,format);}
    internal static Bitmap Render(int width,int height,double ratio,EnemyHealthOptions options,string name,bool locked,bool editing,BarDesign.GlowWorkspace glow,string language="es",bool includeName=true){
        var result=new Bitmap(width+10,height+87,PixelFormat.Format32bppPArgb);using(var g=Graphics.FromImage(result)){
            g.Clear(Color.Transparent);g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;g.SmoothingMode=SmoothingMode.AntiAlias;
            using(var bar=BarDesign.RenderEmissive(width,height,ratio,false,true,1,options.Bar,glow))g.DrawImageUnscaled(bar,0,46);
