            g.CompositingMode=CompositingMode.SourceCopy;using(var clear=new SolidBrush(Color.Transparent))g.FillRectangle(clear,5,51,width,height);g.CompositingMode=CompositingMode.SourceOver;
            using(var track=Rounded(5,51,width,height))using(var brush=new SolidBrush(Color.FromArgb(options.Bar.TrackOpacity,3,6,9)))g.FillPath(brush,track);
            float fill=(float)(width*Math.Max(0,Math.Min(1,ratio)));if(fill>0){using(var stroke=Rounded(5,51,fill,height))using(var brush=new SolidBrush(BarDesign.EnergyColor(ratio,options.Bar)))g.FillPath(brush,stroke);if(options.Bar.Emissive&&options.Bar.GlowPercent>0&&fill>5)using(var pen=new Pen(Color.FromArgb(Math.Min(180,135*options.Bar.GlowPercent/100),(BarDesign.EnergyColor(ratio,options.Bar).R+255)/2,(BarDesign.EnergyColor(ratio,options.Bar).G+255)/2,(BarDesign.EnergyColor(ratio,options.Bar).B+255)/2),1))g.DrawLine(pen,8,52,5+fill-3,52);}
            if(editing)using(var brush=new SolidBrush(Color.FromArgb(1,0,0,0)))g.FillRectangle(brush,0,0,result.Width,result.Height);
            if(includeName&&options.Name.Enabled)EnemyNameOverlay.Draw(g,EnemyNameOverlay.CaptionBounds(new Rectangle(5,51,width,height),options.Name),options.Name,name,locked);

        }return result;
