    void Pulse(){if(disposed||!options.Bar.Enabled)return;var s=Read();bool known=preview||EnemyHealthSignal.Fresh(s,DpsHistory.UtcNow());double now=clock.Elapsed.TotalSeconds;uint current=preview?65:known?s.Current:0,max=preview?100:known?s.Maximum:0;double ratio=max==0?0:(double)current/max;string nextActor=s==null?"":s.Flow+"/"+s.Actor;if(actorKey!=nextActor){actorKey=nextActor;motion.SnapValue(ratio);}motion.Step(now,editing,known,ratio,current,max,options.Bar,known?0:-1);bool show=(editing||known)&&!DpsDesign.ShellUiActive();byte opacity=show?(byte)Math.Round(motion.Opacity*255):(byte)0;if(opacity==0){if(Visible)Hide();texts.Clear();titleOverlay.Clear();distanceOverlay.Clear();speciesOverlay.Clear();lockOverlay.Clear();}else{string name=preview?(targetSignal==null?"Karnif de la Meseta":"Charlotta"):s==null?(owner.Language=="es"?"Vida del enemigo · prueba":"Enemy health · preview"):CaptionOf(s);bool locked=targetSignal==null&&s!=null&&s.Locked;var paint=targetSignal!=null&&s!=null&&s.IsSelf&&options.SelfHighlight?selfOptions:options;string key=Core.Size+"/"+(int)Math.Round(motion.Value*Core.Width)+"/"+BarDesign.EnergyColor(motion.Value,paint.Bar).ToArgb()+"/"+editing+"/"+(paint==selfOptions);if(renderKey!=key){renderKey=key;using(var bitmap=Render(Core.Width,Core.Height,motion.Value,paint,name,false,editing,glow,owner.Language,false)){image.Upload(bitmap);}alpha=0;}if(alpha!=opacity||presented!=Location||!Visible){image.Present(Handle,Left,Top,opacity);alpha=opacity;presented=Location;}texts.Update(Core,options.Bar,known,current,max,opacity,null,-1,true,owner.Language);if(!Visible)Show();if(now>=raise){raise=now+1;OverlayNative.RaiseWithoutFocus(Handle);}titleOverlay.Update(Core,paint.Name,name,false,opacity);if(targetSignal==null){lockOverlay.Update(Core,options.LockText,LockCaption(locked,owner.Language),false,opacity);var detail=options.Details;string metres=detail.Distance&&s!=null&&s.Distance.HasValue?Math.Floor(s.Distance.Value).ToString("0",CultureInfo.In