    protected override void WndProc(ref Message m){if(m.Msg==0x21){m.Result=new IntPtr(3);return;}if(m.Msg==0x84){if(!editing){m.Result=new IntPtr(-1);return;}var p=PointToClient(new Point((short)m.LParam.ToInt64(),(short)(m.LParam.ToInt64()>>16)));m.Result=new IntPtr(BarDesign.HitTest(p.X,p.Y,Width,Height,6));return;}if((m.Msg==0xa5||m.Msg==0x205)&&editing){owner.OpenTrayMenu(Cursor.Position);return;}if(m.Msg==0xa1&&editing){hit=m.WParam.ToInt32();if(hit==2||hit>=10&&hit<=17){original=Core;mouse=Cursor.Position;dragging=true;Capture=true;m.Result=IntPtr.Zero;return;}}if(m.Msg==0x200&&dragging){var delta=new Point(Cursor.Position.X-mouse.X,Cursor.Position.Y-mouse.Y);var next=hit==2?new Rectangle(original.X+delta.X,original.Y+delta.Y,original.Width,original.Height):BarDesign.ResizeBounds(original,delta,hit);options.Bounds=next;options.Normalize();Core=options.Bounds;Pulse();m.Result=IntPtr.Zero;return;}if((m.Msg==0x202||m.Msg==0xa2||m.Msg==0x215)&&dragging){dragging=false;Capture=false;var cfg=owner.Configuration;(targetSignal==null?cfg.EnemyHealth:cfg.EnemyTarget).Bounds=Core;owner.ApplyConfiguration(cfg);m.Result=IntPtr.Zero;return;}base.WndProc(ref m);}
